const r = $input.first().json.r || {};
if (r.ok !== true) throw new Error('Talents-Abruf ' + PL + ': ' + String(r.fehler || 'Die Liste der fälligen Kanäle ist nicht lesbar.').slice(0, 200));
const lauf = $('Portion anfordern').first().json;
