const TAG = /^[0-9]{4}-[0-9]{2}-[0-9]{2}$/;
const out = [];
for (const k of Array.isArray(r.kanaele) ? r.kanaele : []) {
  const id = Number(k && k.kanal_id);
  if (!(id > 0) || erledigt.has(id)) continue;
  const j = { start: true, kanal_id: id, plattform: PL, extern_id: String(k.extern_id || ''), seite_id: String(k.seite_id || ''),
    api: String(k.api || ''), data_api: String(k.data_api || ''), von: String(k.von || ''), bis: String(k.bis || ''), tag: String(k.tag || ''),
    tage: (Array.isArray(k.tage) ? k.tage : []).filter(t => t && TAG.test(String(t.tag)) && Number(t.since) > 0 && Number(t.until) > Number(t.since))
      .map(t => ({ tag: String(t.tag), since: Number(t.since), until: Number(t.until) })),
    seit_unix: Number(k.seit_unix) > 0 ? Number(k.seit_unix) : null,
    zielgruppe_faellig: k.zielgruppe_faellig === true,
    beitraege: (Array.isArray(k.beitraege) ? k.beitraege : []).map(b => ({ extern_id: String(b.extern_id || '') })).filter(b => /^[A-Za-z0-9_.:-]{1,100}$/.test(b.extern_id)),
    erneuern: k.erneuern === true, fehler: null };
  if (k.schluessel_fehler === true || typeof k.schluessel !== 'string' || !k.schluessel.trim()) {
    j.fehler = { code: 'schluessel', text: 'Zugangsschlüssel nicht lesbar.', abgelaufen: false };
  } else if (!/^[A-Za-z0-9_.:-]{1,100}$/.test(j.extern_id) || !API.test(j.api) || (PL === 'youtube' && j.data_api !== 'https://www.googleapis.com/youtube/v3')
             || (PL === 'facebook' && !/^[0-9]{1,30}$/.test(j.seite_id))) {
    j.fehler = { code: 'konto', text: 'Die gespeicherte Konto-ID oder API-Adresse ist ungültig. Bitte den Kanal neu verbinden.', abgelaufen: false };
  } else if (j.erneuern && app.fehler) {
    j.fehler = { code: 'app', text: String(app.fehler).slice(0, 200), abgelaufen: false };
  }
