    gueltig_bis = zahl(b.expires_in) > 0 ? zahl(b.expires_in) : 5184000;
  } else {
    neuer_schluessel = typeof b.refresh_token === 'string' && b.refresh_token.length >= 10 && !/\s/.test(b.refresh_token);
    const rb = PL === 'pinterest' ? zahl(b.refresh_token_expires_in) : (PL === 'tiktok' ? zahl(b.refresh_expires_in) : zahl(b.refresh_token_expires_in));
    gueltig_bis = rb > 0 ? rb : null;
    const sc = typeof b.scope === 'string' ? b.scope.split(/[\s,]+/).filter(x => /^[A-Za-z0-9_.:\/-]{1,120}$/.test(x)) : [];
    berechtigungen = sc.length ? sc : null;
  }
}
return [{ json: { kanal_id: start.kanal_id, start: Object.assign({}, start, { zugang: { ok: !fehler, fehler } }), zugang_ok: !fehler, zugang_fehler: fehler, neuer_schluessel, gueltig_bis, berechtigungen } }];

// ---- Plattform-Modul TikTok (Stefan 18.10.2026, Vertrag Migration 48, 1.5) ----
// open.tiktokapis.com/v2: GET user/info/?fields=… (user.info.basic/stats); POST video/list/?fields=… Body {cursor, max_count ≤ 20}, nur öffentliche
// Videos, neueste zuerst; POST video/query/ Body {filters:{video_ids ≤ 20}} (https://developers.tiktok.com/docs/en/tiktok-api-v2-video-list).
// Nur Gesamtzahlen: Konto als Stand des Tages (likes_count als likes_gesamt, damit nichts als Tageswert summiert wird), Videos lifetime.
// Vorschaubild nicht gespeichert: cover_image_url gilt laut Doku nur 6 Stunden.
const PL = 'tiktok', NAME = 'TikTok';
const ABGELAUFEN_BEI_TOKEN = false;
