  if (!status) return { code: 'netz', roh: '', text: 'TikTok war nicht erreichbar.', klasse: 'temporaer' };
  const code = e && typeof e.code === 'string' ? e.code : 'http' + status;
  const roh = e ? String(e.message || '') : '';
