  const t = zahl(v.create_time);
  beitragSetzen(st, { extern_id: String(v.id), art: 'VIDEO', erstellt: t ? new Date(t * 1000).toISOString() : undefined, link: v.share_url,
    text_inhalt: v.title || v.video_description, werte: { views: v.view_count, likes: v.like_count, comments: v.comment_count, shares: v.share_count } });
}
// Konto (GET) zuerst allein, danach nur POST-Abrufe: so enthält jede Runde nur eine Methode ("POST?" verteilt auf zwei HTTP-Knoten)
function beginnen(st, k) {
  st.offen.push({ art: 'konto', pfad: 'user/info/', query: { fields: 'open_id,display_name,follower_count,following_count,likes_count,video_count' } });
}
