    if (u.open_id !== undefined && String(u.open_id) !== String(st.extern_id)) { st.abbruch = { code: 'konto', text: 'TikTok meldet ein anderes Konto als gespeichert. Bitte den Kanal neu verbinden.', abgelaufen: false, pause: 0 }; return; }
    if (typeof u.display_name === 'string' && u.display_name.trim()) st.d.konto_name = u.display_name.trim();
    kontoWert(st, 'followers_count', u.follower_count);
