    kontoWert(st, 'likes_gesamt', u.likes_count);
    kontoWert(st, 'media_count', u.video_count);
    st.offen.push({ art: 'liste', seite: 1, methode: 'POST', pfad: 'video/list/', query: { fields: VF }, body: { max_count: 20 } });
  } else if (req.art === 'liste') {
