// Nach der Liste: verfolgte Videos, die nicht in der Liste waren, gezielt abfragen (je 20)
function nachEnde(st) {
  const fehlt = st.verfolgt.filter(id => !st.d.beitraege[id] && /^[0-9]{1,30}$/.test(id));
  for (let i = 0; i < fehlt.length; i += 20) st.offen.push({ art: 'abfrage', methode: 'POST', pfad: 'video/query/', query: { fields: VF }, body: { filters: { video_ids: fehlt.slice(i, i + 20) } } });
}
